import React from "react";
import { useForm, Controller } from "react-hook-form";
import {
  TextField,
  Button,
  MenuItem,
  Snackbar,
  Grid,
  Typography,
} from "@material-ui/core";
import { useNavigate, useLocation } from "react-router-dom";

const OrderView = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { product } = location.state || {}; // passed from ProductCard

  const {
    handleSubmit,
    control,
    reset,
    formState: { errors },
  } = useForm();

  const onSubmit = (data) => {
    // Simulate persistence (API call)
    console.log("Order placed:", { ...data, product });
    reset();
    setOpen(true);
    setTimeout(() => navigate("/"), 3000);
  };

  const [open, setOpen] = React.useState(false);

  const weightOptions = [
    "2kg",
    "1kg",
    "500gm",
    "250gm",
    "6 pieces",
    "4 pieces",
  ];

  return (
    <Grid container spacing={2} justifyContent="center" padding={4}>
      <Grid item xs={12}>
        <Typography variant="h4" align="center">
          Place Your Order
        </Typography>
      </Grid>

      <Grid item xs={12}>
        <Typography variant="h6">Item: {product?.name}</Typography>
      </Grid>

      <Grid item xs={12} md={6}>
        <Controller
          name="firstName"
          control={control}
          rules={{ required: true, minLength: 3 }}
          render={({ field }) => (
            <TextField
              {...field}
              label="First Name"
              fullWidth
              error={!!errors.firstName}
              helperText={
                errors.firstName ? "First name must be at least 3 characters" : ""
              }
            />
          )}
        />
      </Grid>

      <Grid item xs={12} md={6}>
        <Controller
          name="lastName"
          control={control}
          rules={{ required: true }}
          render={({ field }) => (
            <TextField
              {...field}
              label="Last Name"
              fullWidth
              error={!!errors.lastName}
              helperText={errors.lastName && "Last name is required"}
            />
          )}
        />
      </Grid>

      <Grid item xs={12} md={6}>
        <Controller
          name="email"
          control={control}
          rules={{
            required: true,
            pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
          }}
          render={({ field }) => (
            <TextField
              {...field}
              label="Email"
              fullWidth
              error={!!errors.email}
              helperText={errors.email && "Enter a valid email"}
            />
          )}
        />
      </Grid>

      <Grid item xs={12} md={6}>
        <Controller
          name="phone"
          control={control}
          rules={{
            required: true,
            pattern: /^[789]\d{9}$/,
          }}
          render={({ field }) => (
            <TextField
              {...field}
              label="Phone"
              fullWidth
              error={!!errors.phone}
              helperText={errors.phone && "Enter a valid 10-digit phone starting with 7, 8, or 9"}
            />
          )}
        />
      </Grid>

      <Grid item xs={12} md={6}>
        <Controller
          name="deliveryDate"
          control={control}
          rules={{
            required: true,
            validate: (value) => new Date(value) >= new Date(),
          }}
          render={({ field }) => (
            <TextField
              {...field}
              label="Delivery Date"
              type="date"
              fullWidth
              InputLabelProps={{ shrink: true }}
              error={!!errors.deliveryDate}
              helperText={errors.deliveryDate && "Choose a valid future date"}
            />
          )}
        />
      </Grid>

      <Grid item xs={12} md={3}>
        <Controller
          name="quantity"
          control={control}
          rules={{ required: true, min: 1 }}
          render={({ field }) => (
            <TextField
              {...field}
              label="Quantity"
              type="number"
              fullWidth
              error={!!errors.quantity}
              helperText={errors.quantity && "Quantity must be at least 1"}
            />
          )}
        />
      </Grid>

      <Grid item xs={12} md={3}>
        <Controller
          name="weight"
          control={control}
          rules={{ required: true }}
          render={({ field }) => (
            <TextField
              {...field}
              select
              label="Weight / Pieces"
              fullWidth
              error={!!errors.weight}
              helperText={errors.weight && "Select a valid option"}
            >
              {weightOptions.map((option) => (
                <MenuItem key={option} value={option}>
                  {option}
                </MenuItem>
              ))}
            </TextField>
          )}
        />
      </Grid>

      <Grid item xs={12} md={6}>
        <Controller
          name="address"
          control={control}
          rules={{ required: true }}
          render={({ field }) => (
            <TextField
              {...field}
              label="Address, City, State"
              fullWidth
              error={!!errors.address}
              helperText={errors.address && "Address is required"}
            />
          )}
        />
      </Grid>

      <Grid item xs={12} md={6}>
        <Controller
          name="zipCode"
          control={control}
          rules={{ required: true, pattern: /^\d{6}$/ }}
          render={({ field }) => (
            <TextField
              {...field}
              label="Zip Code"
              fullWidth
              error={!!errors.zipCode}
              helperText={errors.zipCode && "Zip Code must be a 6-digit number"}
            />
          )}
        />
      </Grid>

      <Grid item xs={12}>
        <Button variant="contained" color="primary" onClick={handleSubmit(onSubmit)}>
          Place Order
        </Button>
      </Grid>

      <Snackbar
        open={open}
        autoHideDuration={3000}
        message="Order placed successfully!"
        onClose={() => setOpen(false)}
      />
    </Grid>
  );
};

export default OrderView;
